import { useState } from 'react';
import type { ChangeEvent } from 'react';
import { Button, Card, Divider, Input, Stack, Stepper, Text } from '@jinx-ui/react';

export type RegistrationValues = {
  fullName: string;
  email: string;
  phone: string;
  country: string;
  city: string;
  street: string;
  zip: string;
};

export type RegistrationFormProps = {
  onSubmit: (values: RegistrationValues) => void;
};

const STEPS = ['Контакты', 'Адрес', 'Проверка'];

const EMPTY_VALUES: RegistrationValues = {
  fullName: '',
  email: '',
  phone: '',
  country: '',
  city: '',
  street: '',
  zip: '',
};

const REVIEW_LABELS: Array<[keyof RegistrationValues, string]> = [
  ['fullName', 'Имя'],
  ['email', 'Email'],
  ['phone', 'Телефон'],
  ['country', 'Страна'],
  ['city', 'Город'],
  ['street', 'Улица, дом'],
  ['zip', 'Индекс'],
];

export default function RegistrationForm({ onSubmit }: RegistrationFormProps) {
  const [step, setStep] = useState(0);
  const [values, setValues] = useState<RegistrationValues>(EMPTY_VALUES);

  const isLastStep = step === STEPS.length - 1;

  const setField =
    (field: keyof RegistrationValues) => (event: ChangeEvent<HTMLInputElement>) => {
      const { value } = event.target;
      setValues((previous) => ({ ...previous, [field]: value }));
    };

  const goBack = () => setStep((current) => Math.max(0, current - 1));
  const goNext = () => setStep((current) => Math.min(STEPS.length - 1, current + 1));

  return (
    <Card className="jx-card" style={{ padding: 'var(--jx-space-6)' }}>
      <Stack direction="column" gap="var(--jx-space-6)">
        <Stepper steps={STEPS} active={step} />

        {step === 0 && (
          <Stack direction="column" gap="var(--jx-space-4)">
            <Input
              label="Имя и фамилия"
              value={values.fullName}
              onChange={setField('fullName')}
              placeholder="Анна Смирнова"
            />
            <Input
              label="Email"
              type="email"
              value={values.email}
              onChange={setField('email')}
              placeholder="anna@example.com"
            />
            <Input
              label="Телефон"
              type="tel"
              value={values.phone}
              onChange={setField('phone')}
              placeholder="+7 900 000-00-00"
            />
          </Stack>
        )}

        {step === 1 && (
          <Stack direction="column" gap="var(--jx-space-4)">
            <Input label="Страна" value={values.country} onChange={setField('country')} />
            <Input label="Город" value={values.city} onChange={setField('city')} />
            <Input label="Улица, дом" value={values.street} onChange={setField('street')} />
            <Input label="Индекс" value={values.zip} onChange={setField('zip')} />
          </Stack>
        )}

        {step === 2 && (
          <Stack direction="column" gap="var(--jx-space-3)">
            <Text weight="medium">Проверьте данные перед отправкой</Text>
            <Divider />
            {REVIEW_LABELS.map(([field, label]) => (
              <Stack key={field} direction="row" justify="space-between" gap="var(--jx-space-4)">
                <Text tone="muted">{label}</Text>
                <Text>{values[field] || '—'}</Text>
              </Stack>
            ))}
          </Stack>
        )}

        <Divider />

        <Stack direction="row" justify="space-between" gap="var(--jx-space-3)">
          <Button variant="secondary" onClick={goBack} disabled={step === 0}>
            Назад
          </Button>
          {isLastStep ? (
            <Button variant="primary" onClick={() => onSubmit(values)}>
              Отправить
            </Button>
          ) : (
            <Button variant="primary" onClick={goNext}>
              Дальше
            </Button>
          )}
        </Stack>
      </Stack>
    </Card>
  );
}

